-- Icon Crafter collaboration backend: initial schema.
--
-- Additive, idempotent and non-destructive: every statement is guarded with
-- IF NOT EXISTS / OR REPLACE, so applying this migration to a database that
-- already contains a superset of the objects is a no-op. Nothing is dropped.
--
-- Timestamps are always TIMESTAMPTZ in UTC. Identifiers are UUIDs generated by
-- the database (`gen_random_uuid()` is built into PostgreSQL 13+).

-- ---------------------------------------------------------------------------
-- Accounts and sessions
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS users (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    email         text        NOT NULL,
    display_name  text        NOT NULL,
    password_hash text        NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    is_active     boolean     NOT NULL DEFAULT true,
    CONSTRAINT users_email_not_empty CHECK (email <> ''),
    CONSTRAINT users_email_len CHECK (char_length(email) <= 320),
    CONSTRAINT users_display_name_len CHECK (char_length(display_name) BETWEEN 1 AND 200),
    CONSTRAINT users_password_hash_len CHECK (char_length(password_hash) BETWEEN 1 AND 1024)
);

-- Case-insensitive uniqueness on the e-mail address. The application stores
-- addresses lowercased, the index also protects rows written by other tools.
CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower_key ON users (lower(email));

CREATE TABLE IF NOT EXISTS sessions (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    token_hash   bytea       NOT NULL UNIQUE,
    created_at   timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    user_agent   text,
    ip           text,
    CONSTRAINT sessions_token_hash_len CHECK (octet_length(token_hash) = 32),
    CONSTRAINT sessions_expiry CHECK (expires_at > created_at)
);

CREATE INDEX IF NOT EXISTS sessions_user_id_idx ON sessions (user_id);
CREATE INDEX IF NOT EXISTS sessions_expires_at_idx ON sessions (expires_at);

-- ---------------------------------------------------------------------------
-- Teams, projects, files
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS teams (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    name       text        NOT NULL,
    created_by uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    is_deleted boolean     NOT NULL DEFAULT false,
    CONSTRAINT teams_name_len CHECK (char_length(name) BETWEEN 1 AND 200)
);

CREATE TABLE IF NOT EXISTS team_members (
    team_id    uuid        NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role       text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (team_id, user_id),
    CONSTRAINT team_members_role CHECK (role IN ('owner', 'admin', 'editor', 'viewer'))
);

CREATE INDEX IF NOT EXISTS team_members_user_id_idx ON team_members (user_id);
CREATE INDEX IF NOT EXISTS team_members_team_role_idx ON team_members (team_id, role);

CREATE TABLE IF NOT EXISTS projects (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    team_id    uuid        NOT NULL REFERENCES teams (id) ON DELETE CASCADE,
    name       text        NOT NULL,
    created_by uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    is_deleted boolean     NOT NULL DEFAULT false,
    CONSTRAINT projects_name_len CHECK (char_length(name) BETWEEN 1 AND 200)
);

CREATE INDEX IF NOT EXISTS projects_team_id_idx ON projects (team_id, is_deleted);

CREATE TABLE IF NOT EXISTS files (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    project_id uuid        NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    name       text        NOT NULL,
    branch_of  uuid        REFERENCES files (id) ON DELETE SET NULL,
    created_by uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    is_deleted boolean     NOT NULL DEFAULT false,
    CONSTRAINT files_name_len CHECK (char_length(name) BETWEEN 1 AND 200),
    CONSTRAINT files_not_own_branch CHECK (branch_of IS NULL OR branch_of <> id)
);

CREATE INDEX IF NOT EXISTS files_project_id_idx ON files (project_id, is_deleted);
CREATE INDEX IF NOT EXISTS files_branch_of_idx ON files (branch_of);
CREATE INDEX IF NOT EXISTS files_created_by_idx ON files (created_by);

-- Versions: full snapshots (kind snapshot|named|branch_base) and compressed
-- delta batches (kind delta). Version history is an append-only DAG.
CREATE TABLE IF NOT EXISTS file_versions (
    id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    file_id          uuid        NOT NULL REFERENCES files (id) ON DELETE CASCADE,
    label            text        NOT NULL DEFAULT '',
    kind             text        NOT NULL,
    parent_version_id uuid       REFERENCES file_versions (id) ON DELETE SET NULL,
    snapshot_json    jsonb,
    delta_json       jsonb,
    created_by       uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at       timestamptz NOT NULL DEFAULT now(),
    op_seq           bigint      NOT NULL DEFAULT 0,
    CONSTRAINT file_versions_kind CHECK (kind IN ('snapshot', 'delta', 'named', 'branch_base')),
    CONSTRAINT file_versions_payload CHECK (snapshot_json IS NOT NULL OR delta_json IS NOT NULL),
    CONSTRAINT file_versions_label_len CHECK (char_length(label) <= 200),
    CONSTRAINT file_versions_op_seq_nonnegative CHECK (op_seq >= 0)
);

CREATE INDEX IF NOT EXISTS file_versions_file_created_idx
    ON file_versions (file_id, created_at DESC);
CREATE INDEX IF NOT EXISTS file_versions_file_kind_idx
    ON file_versions (file_id, kind);
CREATE INDEX IF NOT EXISTS file_versions_parent_idx
    ON file_versions (parent_version_id);

-- The document a file currently resolves to. Added after file_versions exists
-- because of the circular foreign key; the column is NOT NULL in practice once
-- a file is created (the application always writes a branch_base snapshot
-- first), but stays nullable so migration is non-destructive for legacy rows.
ALTER TABLE files
    ADD COLUMN IF NOT EXISTS head_version_id uuid REFERENCES file_versions (id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS files_head_version_idx ON files (head_version_id);

CREATE TABLE IF NOT EXISTS file_collaborators (
    file_id    uuid        NOT NULL REFERENCES files (id) ON DELETE CASCADE,
    user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role       text        NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (file_id, user_id),
    CONSTRAINT file_collaborators_role CHECK (role IN ('view', 'comment', 'edit'))
);

CREATE INDEX IF NOT EXISTS file_collaborators_user_idx ON file_collaborators (user_id);

-- ---------------------------------------------------------------------------
-- Comments
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS comments (
    id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    file_id     uuid        NOT NULL REFERENCES files (id) ON DELETE CASCADE,
    page_id     uuid        NOT NULL,
    node_id     uuid,
    author_id   uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    body        text        NOT NULL,
    parent_id   uuid        REFERENCES comments (id) ON DELETE CASCADE,
    resolved_at timestamptz,
    resolved_by uuid        REFERENCES users (id) ON DELETE SET NULL,
    anchor_x    double precision,
    anchor_y    double precision,
    created_at  timestamptz NOT NULL DEFAULT now(),
    updated_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT comments_body_len CHECK (char_length(body) BETWEEN 1 AND 10000),
    CONSTRAINT comments_resolution CHECK (
        (resolved_at IS NULL AND resolved_by IS NULL)
        OR (resolved_at IS NOT NULL)
    )
);

CREATE INDEX IF NOT EXISTS comments_file_created_idx ON comments (file_id, created_at DESC);
CREATE INDEX IF NOT EXISTS comments_file_page_idx ON comments (file_id, page_id);
CREATE INDEX IF NOT EXISTS comments_parent_idx ON comments (parent_id);

-- ---------------------------------------------------------------------------
-- Share links
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS shares (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    file_id       uuid        NOT NULL REFERENCES files (id) ON DELETE CASCADE,
    token_hash    bytea       NOT NULL UNIQUE,
    permission    text        NOT NULL,
    password_hash text,
    expires_at    timestamptz,
    created_by    uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    revoked_at    timestamptz,
    CONSTRAINT shares_token_hash_len CHECK (octet_length(token_hash) = 32),
    CONSTRAINT shares_permission CHECK (permission IN ('view', 'comment', 'edit'))
);

CREATE INDEX IF NOT EXISTS shares_file_idx ON shares (file_id, created_at DESC);
CREATE INDEX IF NOT EXISTS shares_expires_at_idx ON shares (expires_at);

-- ---------------------------------------------------------------------------
-- Assets
-- ---------------------------------------------------------------------------

-- Content-addressed asset store: one row per unique sha256. `file_id` records
-- the first file the content was uploaded to; `file_assets` is the many-to-many
-- link table that lets identical content be attached to several files without
-- duplicating bytes or authorizing anyone by id alone.
CREATE TABLE IF NOT EXISTS assets (
    id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    file_id       uuid        NOT NULL REFERENCES files (id) ON DELETE CASCADE,
    owner_id      uuid        REFERENCES users (id) ON DELETE SET NULL,
    kind          text        NOT NULL,
    sha256        bytea       NOT NULL UNIQUE,
    mime          text        NOT NULL,
    byte_size     bigint      NOT NULL,
    storage_key   text        NOT NULL,
    original_name text,
    created_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT assets_kind CHECK (kind IN ('image', 'font')),
    CONSTRAINT assets_size_positive CHECK (byte_size > 0),
    CONSTRAINT assets_sha_len CHECK (octet_length(sha256) = 32),
    CONSTRAINT assets_storage_key_len CHECK (char_length(storage_key) BETWEEN 1 AND 512),
    CONSTRAINT assets_original_name_len CHECK (original_name IS NULL OR char_length(original_name) <= 255)
);

CREATE INDEX IF NOT EXISTS assets_file_idx ON assets (file_id);

CREATE TABLE IF NOT EXISTS file_assets (
    file_id    uuid        NOT NULL REFERENCES files (id) ON DELETE CASCADE,
    asset_id   uuid        NOT NULL REFERENCES assets (id) ON DELETE CASCADE,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (file_id, asset_id)
);

CREATE INDEX IF NOT EXISTS file_assets_asset_idx ON file_assets (asset_id);

-- ---------------------------------------------------------------------------
-- Collaboration journal
-- ---------------------------------------------------------------------------

-- Durable op batches. `seq` is the per-file monotonically increasing server
-- sequence clients order against; `batch_id` makes replay idempotent.
CREATE TABLE IF NOT EXISTS op_journal (
    id         bigserial PRIMARY KEY,
    file_id    uuid        NOT NULL REFERENCES files (id) ON DELETE CASCADE,
    batch_id   uuid        NOT NULL,
    batch_json jsonb       NOT NULL,
    actor_id   uuid        REFERENCES users (id) ON DELETE SET NULL,
    seq        bigint      NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT op_journal_seq_positive CHECK (seq > 0),
    CONSTRAINT op_journal_batch_unique UNIQUE (file_id, batch_id),
    CONSTRAINT op_journal_seq_unique UNIQUE (file_id, seq)
);

CREATE INDEX IF NOT EXISTS op_journal_file_seq_idx ON op_journal (file_id, seq);
CREATE INDEX IF NOT EXISTS op_journal_actor_idx ON op_journal (actor_id);

-- ---------------------------------------------------------------------------
-- Audit log and published sites
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS audit_events (
    id          bigserial PRIMARY KEY,
    actor_id    uuid        REFERENCES users (id) ON DELETE SET NULL,
    action      text        NOT NULL,
    target_type text        NOT NULL,
    target_id   text,
    metadata    jsonb       NOT NULL DEFAULT '{}'::jsonb,
    ip          text,
    created_at  timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT audit_events_action_len CHECK (char_length(action) BETWEEN 1 AND 100),
    CONSTRAINT audit_events_target_type_len CHECK (char_length(target_type) BETWEEN 1 AND 100)
);

CREATE INDEX IF NOT EXISTS audit_events_actor_created_idx ON audit_events (actor_id, created_at DESC);
CREATE INDEX IF NOT EXISTS audit_events_created_idx ON audit_events (created_at DESC);
CREATE INDEX IF NOT EXISTS audit_events_target_idx ON audit_events (target_type, target_id);

CREATE TABLE IF NOT EXISTS published_sites (
    id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    file_id    uuid        NOT NULL UNIQUE REFERENCES files (id) ON DELETE CASCADE,
    version_id uuid        REFERENCES file_versions (id) ON DELETE SET NULL,
    slug       text        NOT NULL UNIQUE,
    object_key text        NOT NULL,
    byte_size  bigint      NOT NULL,
    sha256     bytea       NOT NULL,
    created_by uuid        REFERENCES users (id) ON DELETE SET NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT published_sites_slug CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,62})$'),
    CONSTRAINT published_sites_size_positive CHECK (byte_size > 0),
    CONSTRAINT published_sites_sha_len CHECK (octet_length(sha256) = 32)
);

CREATE INDEX IF NOT EXISTS published_sites_created_by_idx ON published_sites (created_by);

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION iconcrafter_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS users_touch_updated_at ON users;
CREATE TRIGGER users_touch_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION iconcrafter_touch_updated_at();

DROP TRIGGER IF EXISTS teams_touch_updated_at ON teams;
CREATE TRIGGER teams_touch_updated_at
    BEFORE UPDATE ON teams
    FOR EACH ROW EXECUTE FUNCTION iconcrafter_touch_updated_at();

DROP TRIGGER IF EXISTS projects_touch_updated_at ON projects;
CREATE TRIGGER projects_touch_updated_at
    BEFORE UPDATE ON projects
    FOR EACH ROW EXECUTE FUNCTION iconcrafter_touch_updated_at();

DROP TRIGGER IF EXISTS files_touch_updated_at ON files;
CREATE TRIGGER files_touch_updated_at
    BEFORE UPDATE ON files
    FOR EACH ROW EXECUTE FUNCTION iconcrafter_touch_updated_at();

DROP TRIGGER IF EXISTS comments_touch_updated_at ON comments;
CREATE TRIGGER comments_touch_updated_at
    BEFORE UPDATE ON comments
    FOR EACH ROW EXECUTE FUNCTION iconcrafter_touch_updated_at();

DROP TRIGGER IF EXISTS published_sites_touch_updated_at ON published_sites;
CREATE TRIGGER published_sites_touch_updated_at
    BEFORE UPDATE ON published_sites
    FOR EACH ROW EXECUTE FUNCTION iconcrafter_touch_updated_at();
